insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('bcbe2af0-0373-56fb-986a-55c7cb1fbf0e', '674226c9-4fc6-5cf5-9726-58bce49e4062', 'Biology · Cells and organisation · Lesson 1: Cells and the microscope', 'MYP 2 · Biology · Cells and organisation', '/g7-bio-cells-1/', 'G7-BIO-CELLS-L1', 23, 100) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-BIO-CELLS-L1', 'Biology · Cells and organisation · Lesson 1: Cells and the microscope', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Unicellular", "Multicellular", "Unicellular", "Multicellular", "Multicellular"], "tip": "Count the cells."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Eyepiece lens", "Objective lens", "Stage", "Fine focus", "Light source"], "tip": "Follow the path of the light."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["×40", "×100", "×400", "×150"], "tip": "Multiply the two numbers."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["bubble", "air"], ["see", "view", "block", "hide", "clear"]], "tips": ["What gets trapped?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["cell"], ["small", "tiny", "too small", "naked eye"], ["bacteri", "disease", "medicine", "microorganism", "cell theory"]], "tips": ["Before and after the microscope."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["swab", "cotton bud", "scrape"], ["slide"], ["stain", "methylene", "dye"], ["cover slip", "coverslip", "lowest", "low power", "focus"]], "tips": ["Collect, put on slide, stain, cover, view."]}]}, "models": {"1": [["Q1", "Cells are much too small for the naked eye to see; we need a microscope to magnify them."], ["Q2", "Bacterium and amoeba are single cells; the oak tree, human and mushroom are made of many cells."]], "2": [["Q3", "Eyepiece: you look through it. Objective: near the specimen. Stage: holds the slide. Fine focus: sharpens. Light source: lights the specimen."]], "3": [["Q4", "10 × 4 = 40; 10 × 10 = 100; 10 × 40 = 400; 15 × 10 = 150."], ["Q5", "Lowering it at an angle pushes out the air so no air bubbles are trapped [1], which would block the view of the cells and make them hard to see clearly [1]."]], "4": [["Q6", "The microscope let scientists see cells for the first time [1], because cells are too small to see with the naked eye [1]; this led to the cell theory and to discovering bacteria that cause disease [1]."]], "5": [["Q7", "Gently scrape the inside of the cheek with a clean cotton swab [1], smear it on a glass slide [1], add a drop of methylene blue stain [1], lower a cover slip and view with the lowest power objective first, then focus [1]."]], "6": [["Exit ticket", "×400; the stain makes parts of the cell such as the nucleus easier to see."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('a80aa26c-9f43-5be0-834e-90292150a073', '674226c9-4fc6-5cf5-9726-58bce49e4062', 'Biology · Cells and organisation · Lesson 2: Plant and animal cells', 'MYP 2 · Biology · Cells and organisation', '/g7-bio-cells-2/', 'G7-BIO-CELLS-L2', 20, 101) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-BIO-CELLS-L2', 'Biology · Cells and organisation · Lesson 2: Plant and animal cells', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Cell membrane", "Nucleus", "Mitochondria", "Ribosome", "Cytoplasm"], "tip": "Think of a factory."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Plant cells only", "Both", "Plant cells only", "Both", "Plant cells only", "Both"], "tip": "Three extras for plants."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["plant"], ["wall", "box", "regular"], ["chloroplast", "green"]], "tips": ["Shape and colour."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["light"], ["photosynthes"]], "tips": ["What do chloroplasts need?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["both"], ["wall"], ["chloroplast"], ["vacuole"]], "tips": ["Two similarities and differences."]}]}, "models": {"1": [["Q1", "Membrane: entry and exit. Nucleus: genetic material. Mitochondria: energy. Ribosome: proteins. Cytoplasm: reactions."]], "2": [["Q2", "Cell wall, chloroplasts and the large vacuole are only in plant cells; nucleus, mitochondria and membrane are in both."]], "3": [["Q3", "It is a plant cell [1]; it has a regular shape because of its cell wall [1] and green chloroplasts [1]."]], "4": [["Q4", "Roots are underground and receive no light [1], so they cannot photosynthesise and do not need chloroplasts, while leaf cells receive light for photosynthesis [1]."]], "5": [["Q5", "Both have a nucleus, cytoplasm, cell membrane and mitochondria [1]; plant cells have a cellulose cell wall whereas animal cells do not [1]; plant cells have chloroplasts [1] and a large permanent vacuole, while animal cells have only small temporary vacuoles [1]."]], "6": [["Exit ticket", "Cell wall, chloroplasts, large permanent vacuole."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('426e712a-36bd-5d62-bfeb-1e471aa8f2a6', '674226c9-4fc6-5cf5-9726-58bce49e4062', 'Biology · Cells and organisation · Lesson 3: Specialised cells', 'MYP 2 · Biology · Cells and organisation', '/g7-bio-cells-3/', 'G7-BIO-CELLS-L3', 18, 102) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-BIO-CELLS-L3', 'Biology · Cells and organisation · Lesson 3: Specialised cells', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Red blood cell", "Nerve cell", "Sperm cell", "Root hair cell", "Palisade cell"], "tip": "Match job to name."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["More room for haemoglobin", "Carries impulses a long way", "Releases energy for swimming", "Sweeps mucus away"], "tip": "Feature → why it helps."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["surface area", "long", "hair", "extension"], ["more water", "absorb", "faster", "quicker"]], "tips": ["Shape → effect."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 4, "pts": [["biconcave", "disc", "shape"], ["surface area"], ["no nucleus"], ["haemoglobin", "hemoglobin", "more oxygen"]], "tips": ["Feature, then why."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["oxygen"], ["less", "block", "stuck", "cannot"], ["respiration", "energy"]], "tips": ["Shape → oxygen → energy."]}]}, "models": {"1": [["Q1", "A large surface area, room for lots of oxygen-carrying substance, small size to fit through capillaries."], ["Q2", "Red blood cell: oxygen. Nerve: impulses. Sperm: fertilisation. Root hair: water. Palisade: photosynthesis."]], "2": [["Q3", "No nucleus: more haemoglobin. Long: impulses travel far. Mitochondria: energy to swim. Cilia: move mucus."]], "3": [["Q4", "It has a long hair-like extension that gives a large surface area [1], so it can absorb more water and minerals from the soil faster [1]."]], "4": [["Q5", "Its biconcave disc shape [1] gives a large surface area for oxygen to diffuse in quickly [1]; it has no nucleus [1], so there is more room for haemoglobin to carry more oxygen [1]."]], "5": [["Q6", "The curved cells carry less oxygen and can get stuck in capillaries [1], so less oxygen reaches the body cells [1]; with less oxygen, less aerobic respiration releases energy, so the person feels tired [1]."]], "6": [["Exit ticket", "Root hair cell: long extension gives a large surface area to absorb water."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('e8e751bd-ea04-5c12-8260-fd64a5842832', '674226c9-4fc6-5cf5-9726-58bce49e4062', 'Biology · Cells and organisation · Lesson 4: From cells to organisms', 'MYP 2 · Biology · Cells and organisation', '/g7-bio-cells-4/', 'G7-BIO-CELLS-L4', 21, 103) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-BIO-CELLS-L4', 'Biology · Cells and organisation · Lesson 4: From cells to organisms', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Organ", "Cell", "Tissue", "Organ system", "Organism", "Organ"], "tip": "Smallest to largest."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Respiratory", "Digestive", "Circulatory", "Nervous", "Digestive"], "tip": "What does the organ do?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["spread"], ["high concentration", "higher concentration", "high to low"], ["particle", "molecule", "random"]], "tips": ["High → low."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["lung"], ["blood", "heart"], ["diffus", "muscle"]], "tips": ["Air → blood → cell."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["independent+temperature"], ["dependent+time", "time taken", "how long"], ["control", "same volume", "same amount", "same drop"], ["repeat", "three times", "average"]], "tips": ["IV, DV, CVs, repeats."]}]}, "models": {"1": [["Q1", "Heart and leaf: organs. Neurone: cell. Muscle: tissue. Heart, blood, vessels: circulatory system. Giraffe: organism."]], "2": [["Q2", "Lungs: respiratory. Stomach and small intestine: digestive. Heart: circulatory. Brain: nervous."]], "3": [["Q3", "The ink slowly spreads out through the water [1] because its particles move from where they are at high concentration to low concentration [1] by the random movement of particles, until they are evenly spread [1]."]], "4": [["Q4", "Oxygen enters the lungs [1] and diffuses into the blood, which the heart pumps around the body [1]; at the muscles, oxygen diffuses from the blood into the muscle cells [1]."]], "5": [["Q5", "The independent variable is the temperature of the water [1]; the dependent variable is the time taken for the colour to spread evenly [1]; control variables are the same volume of water and the same amount of food colouring [1]; repeat three times at each temperature and calculate an average [1]."]], "6": [["Exit ticket", "Cell, tissue, organ, organ system, organism."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('518419e1-a585-5e5f-997f-c9e80014398e', '655fcd9b-449e-5db1-b16b-05c75efeb355', 'Chemistry · Elements, compounds and mixtures · Lesson 1: Atoms and elements', 'MYP 2 · Chemistry · Elements, compounds and mixtures', '/g7-chem-matter-1/', 'G7-CHEM-MATTER-L1', 25, 104) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-CHEM-MATTER-L1', 'Chemistry · Elements, compounds and mixtures · Lesson 1: Atoms and elements', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Element", "Not an element", "Element", "Not an element", "Element", "Not an element"], "tip": "One type of atom only."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["H", "O", "Na", "Fe", "Cu", "Au"], "tip": "Watch the Latin ones."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Metal", "Non-metal", "Metal", "Non-metal", "Metal"], "tip": "Conductor = metal."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["conduct"], ["ductile", "malleable", "bend", "drawn", "wire"]], "tips": ["Two properties."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["dense", "light", "float"], ["flammable", "explode", "burn", "unreactive", "safe"]], "tips": ["Both float, but…"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["grey+metal"], ["conduct"], ["yellow+non"], ["brittle", "crumbl", "does not conduct", "insulat"]], "tips": ["Use both properties."]}]}, "models": {"1": [["Q1", "Examples: copper wire, aluminium foil, oxygen, gold ring (elements); water, wood, plastic (not elements)."], ["Q2", "Oxygen, iron and carbon are elements; water and salt are compounds; air is a mixture."]], "2": [["Q3", "H, O, Na, Fe, Cu, Au."]], "3": [["Q4", "Shiny conductor: metal. Sulfur: non-metal. Copper: metal. Oxygen: non-metal. Malleable: metal."], ["Q5", "Copper is a good conductor of electricity [1] and is ductile, so it can be drawn into thin wires and bent [1]."]], "4": [["Q6", "Both are less dense than air so the balloon floats [1], but hydrogen is flammable and can explode, while helium is unreactive and safe [1]."]], "5": [["Q7", "The grey solid is a metal [1] because it conducts electricity and is malleable [1]; the yellow solid is a non-metal [1] because it does not conduct and is brittle, crumbling when bent [1]."]], "6": [["Exit ticket", "A substance made of only one type of atom, e.g. iron, Fe."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('6c4138b1-d3d0-558d-9562-978a65efdaf9', '655fcd9b-449e-5db1-b16b-05c75efeb355', 'Chemistry · Elements, compounds and mixtures · Lesson 2: Compounds and formulae', 'MYP 2 · Chemistry · Elements, compounds and mixtures', '/g7-chem-matter-2/', 'G7-CHEM-MATTER-L2', 23, 105) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-CHEM-MATTER-L2', 'Chemistry · Elements, compounds and mixtures · Lesson 2: Compounds and formulae', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Element", "Compound", "Compound", "Element", "Compound", "Element"], "tip": "How many different symbols?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Sodium chloride", "Magnesium oxide", "Iron sulfide", "Copper oxide"], "tip": "Metal first, then -ide."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 6, "n": 6, "ans": ["2", "3", "3", "4", "5", "7"], "tip": "Add every atom."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["magnet"], ["new substance", "compound", "different"], ["black", "colour", "glow", "heat"]], "tips": ["Test with a magnet."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["bond", "joined"], ["fixed ratio", "fixed"], ["not bond", "not joined", "not chemically"], ["physical", "any ratio", "separate"]], "tips": ["Bonded vs not bonded."]}]}, "models": {"1": [["Q1", "O₂, Fe and N₂ are elements (one type of atom); H₂O, CO₂ and NaCl are compounds."]], "2": [["Q2", "Sodium chloride; magnesium oxide; iron sulfide; copper oxide."]], "3": [["Q3", "NaCl 2; H₂O 3; CO₂ 3; NH₃ 4; CH₄ 5; H₂SO₄ 7."]], "4": [["Q4", "Before heating, a magnet can pull out the iron because it is only a mixture [1]; after heating, a magnet no longer attracts the product because a new substance, iron sulfide, has formed [1]; the product is a black solid and the mixture glows, showing a reaction [1]."]], "5": [["Q5", "In a compound the atoms of different elements are chemically bonded [1] in a fixed ratio [1]; in a mixture the elements are not chemically joined [1], can be in any ratio and can be separated by physical methods [1]."]], "6": [["Exit ticket", "Magnesium oxide; three atoms."]]}, "labels": {"q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('831c5e42-76ce-55f6-8491-9b9fca3a3557', '655fcd9b-449e-5db1-b16b-05c75efeb355', 'Chemistry · Elements, compounds and mixtures · Lesson 3: Mixtures and separating them', 'MYP 2 · Chemistry · Elements, compounds and mixtures', '/g7-chem-matter-3/', 'G7-CHEM-MATTER-L3', 18, 106) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-CHEM-MATTER-L3', 'Chemistry · Elements, compounds and mixtures · Lesson 3: Mixtures and separating them', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Solute", "Solvent", "Solution", "Insoluble"], "tip": "The solvent does the dissolving."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["dissolve", "water"], ["filter"], ["evaporat", "heat"]], "tips": ["Dissolve, filter, evaporate."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Distillation", "Filtration", "Chromatography", "Evaporation"], "tip": "What do you want to keep?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["boil", "evaporat"], ["condens", "cool"], ["salt+left", "salt+behind", "salt+remain"]], "tips": ["Boil, cool, what stays?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["clean", "drinking", "safe water", "pure"], ["energy", "fuel", "cost", "expensive"], ["brine", "salt waste", "pollut", "carbon"], ["conclu", "overall", "worth", "solar"]], "tips": ["Benefit, cost, environment, judgement."]}]}, "models": {"1": [["Q1", "Salt: solute. Water: solvent. Salty water: solution. Sand: insoluble."]], "2": [["Q2", "Add water and stir so the salt dissolves [1]; filter to remove the sand as residue [1]; heat the filtrate to evaporate the water and leave salt crystals [1]."]], "3": [["Q3", "Seawater: distillation. Sand: filtration. Dyes: chromatography. Crystals: evaporation."]], "4": [["Q4", "The seawater is heated until the water boils and becomes vapour [1]; the vapour is cooled in the condenser and condenses back into pure liquid water [1]; the salt is left behind in the flask because it does not evaporate [1]."]], "5": [["Q5", "Distillation gives a reliable supply of clean, safe drinking water [1], but it needs a lot of energy so it is expensive [1]; burning fuel releases carbon dioxide and the salty brine waste can pollute the sea [1]; overall it is worth it where there is no other water, especially if solar energy is used [1]."]], "6": [["Exit ticket", "Paper chromatography."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('bae8e93a-62d7-564d-a8f7-24d9fafbe5c4', '655fcd9b-449e-5db1-b16b-05c75efeb355', 'Chemistry · Elements, compounds and mixtures · Lesson 4: Physical and chemical changes', 'MYP 2 · Chemistry · Elements, compounds and mixtures', '/g7-chem-matter-4/', 'G7-CHEM-MATTER-L4', 18, 107) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-CHEM-MATTER-L4', 'Chemistry · Elements, compounds and mixtures · Lesson 4: Physical and chemical changes', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Physical", "Chemical", "Physical", "Chemical", "Chemical", "Physical"], "tip": "New substance?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["fizz", "bubble", "gas"], ["warm", "temperature", "heat"]], "tips": ["What did they observe?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Magnesium oxide", "Carbon dioxide", "Iron sulfide", "Copper oxide"], "tip": "Combine the names."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["gas", "carbon dioxide", "water vapour", "smoke"], ["escape", "air", "lost"], ["atom", "same total", "not destroyed", "conserv"]], "tips": ["Where did the mass go?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["chemical"], ["colour", "white", "solid"], ["revers", "new substance", "cannot"]], "tips": ["Can you undo it?"]}]}, "models": {"1": [["Q1", "Melting, dissolving and boiling are physical; burning, rusting and baking are chemical."]], "2": [["Q2", "Bubbles of gas were produced (fizzing) [1] and the temperature increased because the tube got warm [1]."]], "3": [["Q3", "Magnesium oxide; carbon dioxide; iron sulfide; copper oxide."]], "4": [["Q4", "Burning produces gases such as carbon dioxide and water vapour [1] which escape into the air [1]; the atoms are not destroyed, so if you could collect all the products the total mass would be the same [1]."]], "5": [["Q5", "It is a chemical change [1]: the egg white changes colour from clear to white and becomes solid [1], and the change cannot be reversed because new substances have formed [1]."]], "6": [["Exit ticket", "Magnesium + oxygen → magnesium oxide."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('4aa8e27f-50cf-51d9-b1e2-d6753f71afac', '393aeb6f-5855-5673-9dbf-dc1364eed0a2', 'Physics · Forces and motion · Lesson 1: What is a force?', 'MYP 2 · Physics · Forces and motion', '/g7-phys-forces-1/', 'G7-PHYS-FORCES-L1', 23, 108) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-PHYS-FORCES-L1', 'Physics · Forces and motion · Lesson 1: What is a force?', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Shape", "Speed", "Direction", "Shape", "Speed"], "tip": "Faster/slower, turn, or squash?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Non-contact", "Contact", "Non-contact", "Contact", "Contact", "Non-contact"], "tip": "Must they touch?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["weight", "gravity"], ["reaction", "support", "table push", "normal"]], "tips": ["Down and up."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["10 N", "50 N", "500 N", "1000 N"], "tip": "Multiply by 10."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["mass+same"], ["weight+less", "weight+decrease", "weight+smaller"]], "tips": ["Matter vs gravity."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["independent+force", "independent+mass", "independent+weight"], ["dependent+extension", "dependent+length"], ["ruler"], ["mass", "weight", "repeat", "same spring"]], "tips": ["IV, DV, equipment, control."]}]}, "models": {"1": [["Q1", "Gravity (weight) pulling down, the chair pushing up, friction from the floor."], ["Q2", "Sponge and spring: shape. Kicking and braking: speed. Bat: direction."]], "2": [["Q3", "Gravity, magnetism and electrostatic force are non-contact; friction, air resistance and upthrust are contact."]], "3": [["Q4", "Its weight (gravity) pulls it down [1] and the reaction force from the table pushes it up with an equal force [1]."]], "4": [["Q5", "1 kg → 10 N; 5 kg → 50 N; 50 kg → 500 N; 100 kg → 1000 N."], ["Q6", "Her mass stays the same because the amount of matter in her body does not change [1]; her weight is less because the Moon''s gravity is weaker [1]."]], "5": [["Q7", "The independent variable is the force (number of 100 g masses hung) [1]; the dependent variable is the extension of the spring [1], measured with a ruler next to the spring [1]; use the same spring each time and repeat readings to check them [1]."]], "6": [["Exit ticket", "Newtons; 20 N."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('bc1fcbc6-e913-559d-a563-8a7d470d20f2', '393aeb6f-5855-5673-9dbf-dc1364eed0a2', 'Physics · Forces and motion · Lesson 2: Balanced and unbalanced forces', 'MYP 2 · Physics · Forces and motion', '/g7-phys-forces-2/', 'G7-PHYS-FORCES-L2', 16, 109) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-PHYS-FORCES-L2', 'Physics · Forces and motion · Lesson 2: Balanced and unbalanced forces', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["20 N right", "0 N", "30 N left", "80 N right"], "tip": "Same way add, opposite subtract."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["2000"], ["balanced", "equal", "zero resultant", "steady", "constant"]], "tips": ["Steady speed means…"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Stays still", "Speeds up", "Slows down", "Steady speed"], "tip": "Balanced or not?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["air resistance+increase"], ["equal", "balance"], ["steady", "constant", "terminal"]], "tips": ["What happens to air resistance?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["keep moving", "continue", "same speed"], ["no force", "unbalanced", "nothing stops", "no resultant"], ["seat belt", "belt"]], "tips": ["The car stops, but the passenger…"]}]}, "models": {"1": [["Q1", "20 N right; 0 N; 30 N left; 80 N right."]], "2": [["Q2", "The resistive force is 2000 N [1] because at constant speed the forces are balanced and the resultant force is zero [1]."]], "3": [["Q3", "Parked car: stays still. Rocket: speeds up. Cyclist: slows down. Plane: steady speed."]], "4": [["Q4", "As she falls faster, air resistance increases [1] until it is equal to her weight [1]; the forces are balanced so she falls at a constant speed, called terminal velocity [1]."]], "5": [["Q5", "When the car stops, the passenger keeps moving forward at the same speed [1] because no force is acting to slow them down until they hit something [1]; a seat belt provides that force and slows them safely [1]."]], "6": [["Exit ticket", "20 N to the right; the box speeds up to the right (accelerates)."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('664c1f06-760a-5456-a23b-c4fc14781802', '393aeb6f-5855-5673-9dbf-dc1364eed0a2', 'Physics · Forces and motion · Lesson 3: Speed and distance–time graphs', 'MYP 2 · Physics · Forces and motion', '/g7-phys-forces-3/', 'G7-PHYS-FORCES-L3', 20, 110) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-PHYS-FORCES-L3', 'Physics · Forces and motion · Lesson 3: Speed and distance–time graphs', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["10 m/s", "5 m/s", "60 km/h", "2 m/s"], "tip": "Distance ÷ time."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["300 m", "1200 m", "5 s", "50 s"], "tip": "Choose the right form."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Stationary", "Constant speed", "Faster constant speed"], "tip": "Slope = speed."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["400"], ["5 m", "5 metres per second"]], "tips": ["Distance ÷ time."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["800"], ["500"], ["1.6", "1 6"]], "tips": ["Total distance ÷ total time."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["tape", "measure the distance", "trundle"], ["stopwatch", "timer", "time"], ["divide", "distance ÷", "speed ="], ["repeat", "average", "three"]], "tips": ["Distance, time, calculate, repeat."]}]}, "models": {"1": [["Q1", "100/10 = 10 m/s; 50/10 = 5 m/s; 120/2 = 60 km/h; 20/10 = 2 m/s."]], "2": [["Q2", "10 × 30 = 300 m; 20 × 60 = 1200 m; 100/20 = 5 s; 500/10 = 50 s."]], "3": [["Q3", "Flat: stationary. Sloping: constant speed. Steeper: faster."], ["Q4", "Speed = 400 m ÷ 80 s [1] = 5 m/s [1]."]], "4": [["Q5", "Total distance = 600 + 200 = 800 m [1]; total time = 300 + 100 + 100 = 500 s [1]; average speed = 800 ÷ 500 = 1.6 m/s [1]."]], "5": [["Q6", "Measure the distance across the field with a tape measure [1]; time the run with a stopwatch [1]; calculate speed by dividing the distance by the time [1]; repeat three times and calculate an average to reduce the effect of reaction time [1]."]], "6": [["Exit ticket", "50 km/h."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('74bfd0d2-578a-5278-8e9b-52a079150375', '393aeb6f-5855-5673-9dbf-dc1364eed0a2', 'Physics · Forces and motion · Lesson 4: Friction and air resistance', 'MYP 2 · Physics · Forces and motion', '/g7-phys-forces-4/', 'G7-PHYS-FORCES-L4', 19, 111) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G7-PHYS-FORCES-L4', 'Physics · Forces and motion · Lesson 4: Friction and air resistance', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Useful", "Useful", "A problem", "Useful", "A problem"], "tip": "Do we want it here?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["surface area", "streamlin", "smaller area"], ["air resistance", "drag"]], "tips": ["Shape → drag."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Reduces friction", "Increases friction", "Increases friction", "Reduces friction", "Reduces friction"], "tip": "Grip or slide?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["friction", "resistance"], ["oil", "lubric"], ["energy", "heat", "waste"]], "tips": ["Less friction → ?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["independent+surface", "surface"], ["dependent+force", "forcemeter", "reading"], ["same shoe", "same mass", "same weight"], ["repeat", "average"]], "tips": ["IV, DV, control, repeats."]}]}, "models": {"1": [["Q1", "They get warm because friction turns kinetic energy into heat."], ["Q2", "Grip, brakes and holding a pencil are useful; engine wear and a slowing sledge are problems."]], "2": [["Q3", "Crouching makes their body more streamlined with a smaller surface area facing the air [1], which reduces air resistance so they can go faster [1]."]], "3": [["Q4", "Oil, wax and ball bearings reduce; treads and chalk increase."]], "4": [["Q5", "Correctly pumped tyres and oil reduce friction [1] between moving parts and with the road, because the oil lubricates the parts [1]; less energy is wasted as heat, so less fuel is needed [1]."]], "5": [["Q6", "The independent variable is the type of surface [1]; the dependent variable is the force on the forcemeter needed to move the shoe [1]; keep the same shoe with the same mass inside it [1]; repeat three times on each surface and calculate an average [1]."]], "6": [["Exit ticket", "Increase: tyre treads. Reduce: oil as a lubricant."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
