insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('5be7687e-24f6-58e5-896c-1638240d18f2', '2d65e8a4-5d49-57db-b2f0-d03a21b2553a', 'Chemistry · Acids, bases and neutralisation · Lesson 1: Acids, alkalis and indicators', 'MYP 3 · Chemistry · Acids, bases and neutralisation', '/g8-chem-acids-1/', 'G8-CHEM-ACIDS-L1', 21, 100) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G8-CHEM-ACIDS-L1', 'Chemistry · Acids, bases and neutralisation · Lesson 1: Acids, alkalis and indicators', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Acid", "Alkali", "Neutral", "Acid", "Alkali", "Neutral"], "tip": "Sour = acid; soapy = alkali."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 4, "pts": [["goggles", "eye protection"], ["eye", "splash"], ["wash", "water", "spill", "dilute", "small"], ["skin", "burn", "corros", "irritat"]], "tips": ["What could go wrong?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Red", "Blue", "No change", "No change", "Blue"], "tip": "Acids make red; alkalis make blue."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["neutral"], ["no change", "neither", "not acid", "not alkali"]], "tips": ["Neither changed."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["chop", "cut", "boil", "hot water", "soak"], ["filter", "strain"], ["add", "drop", "colour", "compare"], ["goggles", "safety", "small"]], "tips": ["Make, filter, test, stay safe."]}]}, "models": {"1": [["Q1", "Acids: vinegar, lemon juice, fizzy drinks. Alkalis: soap, toothpaste, oven cleaner."], ["Q2", "Vinegar and lemon juice: acids. Oven cleaner and soap: alkalis. Water and salt solution: neutral."]], "2": [["Q3", "Wear safety goggles [1] to protect the eyes from splashes [1]; wash any spills off the skin with plenty of water [1] because the acid is an irritant and can burn the skin [1]."]], "3": [["Q4", "Vinegar: red. Soap: blue. Water: no change. Lemon on red litmus: stays red (no change). Oven cleaner: blue."]], "4": [["Q5", "The solution is neutral [1] because neither litmus paper changed colour, so it is not an acid and not an alkali [1]."]], "5": [["Q6", "Chop red cabbage and soak it in hot water [1]; filter or strain to collect the purple juice [1]; add a few drops to each liquid and compare the colour (red = acid, green = alkali) [1]; wear goggles and use small amounts [1]."]], "6": [["Exit ticket", "Red."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('1f8ef5b4-3736-5d95-b60b-3c1330045840', '2d65e8a4-5d49-57db-b2f0-d03a21b2553a', 'Chemistry · Acids, bases and neutralisation · Lesson 2: The pH scale', 'MYP 3 · Chemistry · Acids, bases and neutralisation', '/g8-chem-acids-2/', 'G8-CHEM-ACIDS-L2', 19, 101) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G8-CHEM-ACIDS-L2', 'Chemistry · Acids, bases and neutralisation · Lesson 2: The pH scale', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Strong acid", "Weak acid", "Neutral", "Weak alkali", "Strong alkali"], "tip": "7 is the middle."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["pH 1", "pH 5", "pH 7", "pH 10", "pH 13"], "tip": "Rainbow order."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["lime", "alkali", "base"], ["neutralis", "raise", "increase", "less acid"]], "tips": ["Raise the pH."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["A"], ["lower"], ["rise", "increase", "closer to 7", "towards 7"]], "tips": ["Lower = more acidic."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["cola"], ["orange"], ["milk"], ["enamel", "teeth", "tooth", "acid+dissolve", "acid+damage"]], "tips": ["Lowest pH first."]}]}, "models": {"1": [["Q1", "pH 1 strong acid; 5 weak acid; 7 neutral; 9 weak alkali; 14 strong alkali."]], "2": [["Q2", "Red 1; yellow 5; green 7; blue 10; purple 13."]], "3": [["Q3", "She should add lime (an alkali/base) to the soil [1] to neutralise some of the acid and raise the pH towards 6.5 [1]."]], "4": [["Q4", "Solution A is more acidic [1] because it has a lower pH [1]; adding water dilutes it so its pH rises towards 7 [1]."]], "5": [["Q5", "Most acidic first: cola (pH 3) [1], then orange juice (pH 4) [1], then milk (pH 6.5) [1], then water (pH 7); cola is strongly acidic, so the acid slowly dissolves and damages tooth enamel [1]."]], "6": [["Exit ticket", "pH 7; green."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('3c4629cb-6119-510d-8d2a-188ae52ac6d8', '2d65e8a4-5d49-57db-b2f0-d03a21b2553a', 'Chemistry · Acids, bases and neutralisation · Lesson 3: Neutralisation and salts', 'MYP 3 · Chemistry · Acids, bases and neutralisation', '/g8-chem-acids-3/', 'G8-CHEM-ACIDS-L3', 16, 102) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G8-CHEM-ACIDS-L3', 'Chemistry · Acids, bases and neutralisation · Lesson 3: Neutralisation and salts', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 1, "n": 1, "ans": ["Salt + water"], "tip": "Two products."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Sodium chloride", "Copper sulfate", "Potassium nitrate", "Calcium chloride", "Magnesium sulfate"], "tip": "Metal first, then from the acid."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 4, "pts": [["add", "excess", "until no more"], ["warm", "stir", "heat"], ["filter"], ["evaporat", "crystal"]], "tips": ["Add, filter, evaporate."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["base", "alkali"], ["neutralis"], ["excess acid", "stomach acid", "hydrochloric"]], "tips": ["Base + acid."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["wasp", "alkali"], ["bee", "acid"], ["not every", "not all", "wrong", "only"]], "tips": ["Which stings are which?"]}]}, "models": {"1": [["Q1", "Acid + alkali → salt + water."], ["Q2", "It starts red (pH 1), goes through orange and yellow, reaches green (pH 7), then turns blue/purple if too much alkali is added."]], "2": [["Q3", "Sodium chloride; copper sulfate; potassium nitrate; calcium chloride; magnesium sulfate."]], "3": [["Q4", "Add copper oxide to warm sulfuric acid a little at a time [1], stirring until no more dissolves (excess) [1]; filter to remove the excess copper oxide [1]; evaporate some water and leave the solution to form crystals [1]."]], "4": [["Q5", "The tablet contains a base such as magnesium hydroxide [1] which neutralises [1] the excess hydrochloric acid in the stomach, raising the pH and relieving the pain [1]."]], "5": [["Q6", "Vinegar is an acid, so it can neutralise an alkaline wasp sting [1]; a bee sting is acidic, so vinegar would not neutralise it and baking soda (a base) is needed [1]; so the advice is wrong for every sting, it only works for some [1]."]], "6": [["Exit ticket", "Hydrochloric acid + sodium hydroxide → sodium chloride + water."]]}, "labels": {"q1_1": "Q2", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('ca6f16f2-b1a3-521a-ae98-a90db075a4a2', '2d65e8a4-5d49-57db-b2f0-d03a21b2553a', 'Chemistry · Acids, bases and neutralisation · Lesson 4: Acids with metals and carbonates', 'MYP 3 · Chemistry · Acids, bases and neutralisation', '/g8-chem-acids-4/', 'G8-CHEM-ACIDS-L4', 16, 103) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G8-CHEM-ACIDS-L4', 'Chemistry · Acids, bases and neutralisation · Lesson 4: Acids with metals and carbonates', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Magnesium chloride + hydrogen", "Zinc sulfate + hydrogen", "Iron chloride + hydrogen"], "tip": "Salt + hydrogen."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["lighted splint", "lit splint", "burning splint"], ["squeaky pop", "pop"]], "tips": ["Flame and sound."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Hydrogen", "Carbon dioxide", "Squeaky pop", "Limewater turns milky"], "tip": "Metal or carbonate?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["calcium carbonate", "carbonate"], ["react", "dissolve", "erode", "wear"], ["carbon dioxide+water", "calcium chloride", "calcium sulfate", "salt"]], "tips": ["Carbonate + acid."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["independent+metal", "type of metal"], ["volume of gas", "bubbles", "syringe", "rate"], ["same volume", "same concentration", "same mass", "same size"], ["goggles", "repeat"]], "tips": ["IV, DV, CVs, safety."]}]}, "models": {"1": [["Q1", "Magnesium chloride + hydrogen; zinc sulfate + hydrogen; iron chloride + hydrogen."]], "2": [["Q2", "Hold a lighted splint at the mouth of the test tube [1]; hydrogen burns with a squeaky pop [1]."]], "3": [["Q3", "Zinc: hydrogen (squeaky pop). Chalk: carbon dioxide (limewater milky)."]], "4": [["Q4", "Limestone is calcium carbonate [1], which reacts with the acid in rain and slowly erodes away [1]: calcium carbonate + sulfuric acid → calcium sulfate + water + carbon dioxide [1]."]], "5": [["Q5", "The independent variable is the type of metal [1]; measure the volume of hydrogen collected in a gas syringe in one minute [1]; keep the same volume and concentration of acid and the same mass of metal [1]; wear goggles and repeat each test [1]."]], "6": [["Exit ticket", "Carbon dioxide; it turns limewater milky."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('9fbc50c5-d85c-5f35-84a2-bec311aadc84', '28cf0b61-3275-5fc3-b21c-7dc27b7d1021', 'Physics · Energy · Lesson 1: Energy stores and transfers', 'MYP 3 · Physics · Energy', '/g8-phys-energy-1/', 'G8-PHYS-ENERGY-L1', 19, 104) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G8-PHYS-ENERGY-L1', 'Physics · Energy · Lesson 1: Energy stores and transfers', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Kinetic", "Gravitational potential", "Chemical", "Thermal", "Elastic", "Chemical"], "tip": "Moving, high, food/fuel, hot, stretched."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["gravitational"], ["kinetic"], ["thermal", "sound", "heat"]], "tips": ["High → falling → landing."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Chemical → kinetic", "Kinetic → thermal", "Chemical → thermal", "Gravitational → kinetic"], "tip": "Start → end."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["chemical"], ["kinetic", "gravitational"], ["thermal", "heat", "surroundings"]], "tips": ["Food → movement → ?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["gravitational", "height"], ["kinetic"], ["friction", "air resistance", "thermal", "wasted", "lost"]], "tips": ["Energy is transferred to the surroundings."]}]}, "models": {"1": [["Q1", "Runner: kinetic. Book: gravitational. Battery and charcoal: chemical. Tea: thermal. Rubber band: elastic."]], "2": [["Q2", "The ball starts with energy in its gravitational potential store [1]; as it falls this is transferred to its kinetic store [1]; when it hits the ground energy is transferred to the thermal store of the surroundings and as sound [1]."]], "3": [["Q3", "Car: chemical → kinetic. Brakes: kinetic → thermal. Cooker: chemical → thermal. Dam: gravitational → kinetic."]], "4": [["Q4", "Energy in the chemical store of the food is transferred by the muscles [1] to the kinetic store of the bike and the gravitational store as she climbs [1]; much is transferred to thermal stores, warming her body and the surroundings [1]."]], "5": [["Q5", "At the top the car has energy in its gravitational store, which is transferred to its kinetic store as it goes down [1]; going up the next hill kinetic energy is transferred back to gravitational energy [1]; some energy is transferred to thermal energy by friction and air resistance, so the car cannot reach the same height again [1]."]], "6": [["Exit ticket", "Elastic; chemical."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('8861a61c-49a9-57e3-bc14-774253b73dc1', '28cf0b61-3275-5fc3-b21c-7dc27b7d1021', 'Physics · Energy · Lesson 2: Conservation of energy and efficiency', 'MYP 3 · Physics · Energy', '/g8-phys-energy-2/', 'G8-PHYS-ENERGY-L2', 20, 105) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G8-PHYS-ENERGY-L2', 'Physics · Energy · Lesson 2: Conservation of energy and efficiency', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Useful", "Wasted", "Useful", "Wasted", "Useful"], "tip": "What do we want the device for?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["80"], ["heat", "thermal"]], "tips": ["In = out."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["10%", "25%", "50%", "80%"], "tip": "Useful ÷ total × 100."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["300"], ["60"]], "tips": ["Useful ÷ total × 100."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["efficien"], ["less", "wasted", "heat"], ["fuel", "carbon", "power station", "emission", "electricity"]], "tips": ["Less waste → less fuel."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["90"], ["75"], ["kettle A", "A is"], ["less wasted", "less energy", "cheaper", "saves"]], "tips": ["Calculate then judge."]}]}, "models": {"1": [["Q1", "Lamp light, speaker sound and fan movement are useful; lamp heat and charger heat are wasted."]], "2": [["Q2", "100 − 20 = 80 J is wasted [1], mostly as heat (thermal energy) to the surroundings [1]."]], "3": [["Q3", "10%; 25%; 50%; 80%."], ["Q4", "Efficiency = 300 ÷ 500 × 100 [1] = 60% [1]."]], "4": [["Q5", "LEDs are more efficient [1], so less energy is wasted as heat and less electricity is needed for the same light [1]; power stations burn less fuel, so less carbon dioxide is released [1]."]], "5": [["Q6", "Kettle A: 1800 ÷ 2000 × 100 = 90% [1]; kettle B: 1500 ÷ 2000 × 100 = 75% [1]; buy kettle A [1] because less energy is wasted, so it boils water faster and costs less to run [1]."]], "6": [["Exit ticket", "Energy cannot be created or destroyed, only transferred from one store to another."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('97678a84-d254-50dd-be8b-7a96e00678de', '28cf0b61-3275-5fc3-b21c-7dc27b7d1021', 'Physics · Energy · Lesson 3: Heat transfer: conduction, convection and radiation', 'MYP 3 · Physics · Energy', '/g8-phys-energy-3/', 'G8-PHYS-ENERGY-L3', 22, 106) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G8-PHYS-ENERGY-L3', 'Physics · Energy · Lesson 3: Heat transfer: conduction, convection and radiation', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Good conductor", "Insulator", "Good conductor", "Insulator", "Insulator"], "tip": "Metals conduct."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["less dense", "expand"], ["rise"], ["sink", "cool", "current"]], "tips": ["Hot water rises."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Radiation", "Conduction", "Convection", "Radiation", "Convection"], "tip": "Solid, fluid or wave?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["reflect", "poor absorb", "absorb less"], ["radiation", "infrared", "cool"]], "tips": ["Colour and radiation."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["vacuum"], ["conduction+convection", "no particles"], ["silver", "shiny", "reflect", "radiation"]], "tips": ["One feature per transfer."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["independent+material", "type of material"], ["temperature", "thermometer"], ["same volume", "same starting temperature", "same thickness", "same time"], ["repeat", "graph", "every"]], "tips": ["IV, DV, CVs, recording."]}]}, "models": {"1": [["Q1", "Copper and aluminium conduct; wool, plastic and trapped air insulate."]], "2": [["Q2", "Water heated at the bottom expands and becomes less dense [1], so it rises [1]; cooler, denser water sinks to be heated, setting up a convection current that heats all the water [1]."]], "3": [["Q3", "Sun and fire beside you: radiation. Spoon: conduction. Hot air and warm water rising: convection."], ["Q4", "White surfaces reflect most of the Sun''s infrared radiation and absorb less [1], so the house stays cooler inside [1]."]], "4": [["Q5", "The vacuum between the walls [1] has no particles, so no conduction or convection can happen [1]; the silvered walls reflect infrared radiation back into the drink [1]."]], "5": [["Q6", "The independent variable is the type of material [1]; measure the temperature of the hot water with a thermometer [1]; keep the same volume and starting temperature of water and the same thickness of material [1]; record every two minutes, repeat and plot a cooling graph [1]."]], "6": [["Exit ticket", "Radiation (infrared)."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('5f55ec27-1460-5a04-be50-62d775a9e168', '28cf0b61-3275-5fc3-b21c-7dc27b7d1021', 'Physics · Energy · Lesson 4: Energy resources', 'MYP 3 · Physics · Energy', '/g8-phys-energy-4/', 'G8-PHYS-ENERGY-L4', 20, 107) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G8-PHYS-ENERGY-L4', 'Physics · Energy · Lesson 4: Energy resources', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Non-renewable", "Renewable", "Renewable", "Non-renewable", "Renewable", "Non-renewable"], "tip": "Will it run out?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["steam", "hot water"], ["turbine"], ["generator"]], "tips": ["Steam → turbine → generator."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Coal", "Solar", "Hydroelectric", "Geothermal"], "tip": "Think of each problem."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["carbon dioxide"], ["greenhouse", "trap"], ["warm", "temperature", "climate"]], "tips": ["Gas → effect."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["sun", "sunny", "sunshine"], ["no fuel", "cheap to run", "renewable", "no emission"], ["night", "battery", "cost", "cloud"], ["conclu", "overall", "recommend", "best"]], "tips": ["Pros, cons, judgement."]}]}, "models": {"1": [["Q1", "Coal, gas and uranium are non-renewable; wind, geothermal and solar are renewable."]], "2": [["Q2", "Hot steam from deep underground [1] is piped to spin a turbine [1], which turns a generator to produce electricity [1]."]], "3": [["Q3", "Coal: CO₂. Solar: no output at night. Hydroelectric: dams. Geothermal: volcanic areas."]], "4": [["Q4", "Burning coal releases carbon dioxide [1], a greenhouse gas that traps heat in the atmosphere [1], increasing Earth''s average temperature and changing the climate [1]."]], "5": [["Q5", "Northern Kenya has strong sunshine all year [1]; solar is renewable, has no fuel cost and no emissions [1]; but panels give no power at night, so batteries are needed, which add cost [1]; overall solar with batteries is the best choice for a remote school [1]."]], "6": [["Exit ticket", "Geothermal and hydroelectric (also wind, solar)."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
