insert into public.topics (id, subject_id, programme, name, summary, sort_order, parent_id) select '41b80b32-d95f-5bb1-b5c9-3f22d7baaf15', s.id, 'MYP 4', 'Physics · Electricity', 'Grade 9 Physics', 101, '31ac6b73-081c-5adc-a181-79eca8995b86' from public.subjects s where s.name = 'MYP Science' on conflict (id) do nothing;
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('3e665488-1ab6-5be1-9cb7-a58f7f1ed3a6', 'fb77891f-b5d2-5aee-a633-049dadfe5def', 'Chemistry · Atomic structure and the periodic table · Lesson 1: Inside the atom', 'MYP 4 · Chemistry · Atomic structure and the periodic table', '/g9-chem-atoms-1/', 'G9-CHEM-ATOMS-L1', 18, 100) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G9-CHEM-ATOMS-L1', 'Chemistry · Atomic structure and the periodic table · Lesson 1: Inside the atom', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Proton", "Neutron", "Electron", "Electron", "Neutron"], "tip": "Charge and position."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["proton", "positive"], ["equal", "same number", "balance"]], "tips": ["Plus and minus."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Thomson", "Rutherford", "Bohr", "Dalton", "Chadwick"], "tip": "In time order."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["through", "empty space"], ["bounce", "deflect", "back"], ["nucleus", "dense", "concentrated", "positive centre"]], "tips": ["Two observations, one conclusion."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["small", "tiny", "cannot see"], ["evidence", "experiment", "technology", "equipment"], ["change", "improve", "replace", "new model"]], "tips": ["Size, tools, evidence."]}]}, "models": {"1": [["Q1", "Positive in nucleus: proton. Neutral in nucleus: neutron. Negative, tiny mass, in shells: electron."]], "2": [["Q2", "Protons are positive and electrons are negative [1]; an atom has the same number of protons as electrons, so the charges balance [1]."]], "3": [["Q3", "Dalton: spheres. Thomson: plum pudding. Rutherford: nucleus. Bohr: shells. Chadwick: neutron."]], "4": [["Q4", "Most alpha particles passed straight through, so the atom is mostly empty space [1]; a few were deflected or bounced back [1], which shows the positive charge and mass are concentrated in a tiny dense nucleus, not spread out as in the plum pudding [1]."]], "5": [["Q5", "Atoms are far too small to see directly [1], so scientists had to wait for new technology and experiments such as cathode rays and gold foil to provide evidence [1]; each time new evidence did not fit, the model had to be changed and improved [1]."]], "6": [["Exit ticket", "Proton +1, neutron 0, electron −1."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('1d7c1d04-5e80-5b5c-8210-88244a79fc22', 'fb77891f-b5d2-5aee-a633-049dadfe5def', 'Chemistry · Atomic structure and the periodic table · Lesson 2: Atomic number, mass number and isotopes', 'MYP 4 · Chemistry · Atomic structure and the periodic table', '/g9-chem-atoms-2/', 'G9-CHEM-ATOMS-L2', 18, 101) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G9-CHEM-ATOMS-L2', 'Chemistry · Atomic structure and the periodic table · Lesson 2: Atomic number, mass number and isotopes', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["11", "11", "12", "23"], "tip": "A − Z = neutrons."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["13 protons", "protons 13", "protons = 13", "protons: 13"], ["13 electrons", "electrons 13", "electrons = 13", "electrons: 13"], ["14"]], "tips": ["Z, Z, A − Z."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["6", "7", "8"], "tip": "Mass number − 6."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["same+proton", "6 protons"], ["different+neutron"]], "tips": ["What is the same, what differs?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["living", "alive", "take in"], ["decay", "radioactive"], ["amount", "less", "measure", "rate"]], "tips": ["Life, death, decay."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["isotope"], ["35+37"], ["average", "mean", "abundance", "percentage"]], "tips": ["Two isotopes, different amounts."]}]}, "models": {"1": [["Q1", "Protons 11; electrons 11; neutrons 23 − 11 = 12; mass number 23."]], "2": [["Q2", "It has 13 protons [1], 13 electrons [1] and 27 − 13 = 14 neutrons [1]."]], "3": [["Q3", "12 − 6 = 6; 13 − 6 = 7; 14 − 6 = 8."], ["Q4", "Both have 6 protons, so both are carbon [1], but they have different numbers of neutrons (6 and 8) [1]."]], "4": [["Q5", "While the animal was alive it took in carbon-14 [1]; after death the carbon-14 decays because it is radioactive [1]; measuring how much is left and knowing the rate of decay gives the age [1]."]], "5": [["Q6", "Chlorine has two isotopes [1], chlorine-35 and chlorine-37 [1]; the relative atomic mass is the average mass weighted by how common each isotope is (75% and 25%), giving 35.5 [1]."]], "6": [["Exit ticket", "10."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('ad8a170e-58e2-5a83-845e-4080e1b24df5', 'fb77891f-b5d2-5aee-a633-049dadfe5def', 'Chemistry · Atomic structure and the periodic table · Lesson 3: Electron arrangement', 'MYP 4 · Chemistry · Atomic structure and the periodic table', '/g9-chem-atoms-3/', 'G9-CHEM-ATOMS-L3', 18, 102) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G9-CHEM-ATOMS-L3', 'Chemistry · Atomic structure and the periodic table · Lesson 3: Electron arrangement', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["2,1", "2,8", "2,8,1", "2,8,7", "2,8,8,2"], "tip": "2, then 8, then 8."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["2,8,2", "2.8.2", "2 8 2"], ["three shells", "3 shells", "two in the outer", "2 in the outer", "outer shell"]], "tips": ["2 + 8 + 2."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Group 1, period 3", "Group 7, period 3", "Group 2, period 2", "Group 0, period 2"], "tip": "Last number = group; count of numbers = period."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["neon+full"], ["sodium+one", "sodium+1 "], ["lose", "react to", "gain"]], "tips": ["Look at the outer shells."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["2,8,8,1", "2.8.8.1", "2 8 8 1"], ["group 1"], ["period 4"], ["reactive", "metal", "water"]], "tips": ["Fill the shells."]}]}, "models": {"1": [["Q1", "Li 2,1; Ne 2,8; Na 2,8,1; Cl 2,8,7; Ca 2,8,8,2."]], "2": [["Q2", "Magnesium is 2,8,2 [1]: three shells with 2 electrons in the first, 8 in the second and 2 in the outer shell [1]."]], "3": [["Q3", "2,8,1: group 1 period 3. 2,8,7: group 7 period 3. 2,2: group 2 period 2. 2,8: full shell, group 0 period 2."]], "4": [["Q4", "Neon (2,8) has a full outer shell so it is stable and does not need to react [1]; sodium (2,8,1) has one electron in its outer shell [1], which it loses easily in reactions to get a full shell [1]."]], "5": [["Q5", "X is 2,8,8,1 [1]; it is in group 1 [1] and period 4 [1]; it is a very reactive metal that reacts vigorously with water (it is potassium) [1]."]], "6": [["Exit ticket", "2,8,7; group 7."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('414380f6-2524-5568-9870-4566d854966c', 'fb77891f-b5d2-5aee-a633-049dadfe5def', 'Chemistry · Atomic structure and the periodic table · Lesson 4: The periodic table: groups 1, 7 and 0', 'MYP 4 · Chemistry · Atomic structure and the periodic table', '/g9-chem-atoms-4/', 'G9-CHEM-ATOMS-L4', 18, 103) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G9-CHEM-ATOMS-L4', 'Chemistry · Atomic structure and the periodic table · Lesson 4: The periodic table: groups 1, 7 and 0', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Group 1", "Group 7", "Group 0", "Transition metals"], "tip": "Named groups."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["float", "fizz", "bubble", "move"], ["melt", "ball", "disappear"], ["sodium hydroxide+hydrogen"]], "tips": ["Observations + equation."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Increases", "Decreases", "Increases", "Decreases"], "tip": "Opposite trends."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["more shells", "further", "larger"], ["attract", "pull"], ["lose", "lost"]], "tips": ["Distance → attraction → losing."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["very", "more reactive", "violent", "explo"], ["hydrogen", "hydroxide"], ["oil", "sealed", "under"], ["air", "water", "moisture", "oxygen"]], "tips": ["Trend + safety."]}]}, "models": {"1": [["Q1", "Alkali metals: group 1. Halogens: group 7. Noble gases: group 0. Iron and copper: transition metals."]], "2": [["Q2", "Sodium floats and fizzes, moving around the surface [1]; it melts into a ball and disappears [1]; sodium + water → sodium hydroxide + hydrogen [1]."]], "3": [["Q3", "Group 1 reactivity increases and melting point decreases; group 7 reactivity decreases and melting point increases."]], "4": [["Q4", "Potassium has more shells, so its outer electron is further from the nucleus [1]; the electron is less strongly attracted by the nucleus [1], so it is lost more easily in reactions [1]."]], "5": [["Q5", "Caesium is further down group 1 so it reacts even more violently, possibly explosively [1], forming caesium hydroxide and hydrogen [1]; it should be stored in a sealed container under oil [1] to keep it away from air and moisture [1]."]], "6": [["Exit ticket", "Group 1; it increases down the group."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('be9b2872-abc5-5f3c-8f56-9f01ef8c8fcb', '41b80b32-d95f-5bb1-b5c9-3f22d7baaf15', 'Physics · Electricity · Lesson 1: Charge, current and circuits', 'MYP 4 · Physics · Electricity', '/g9-phys-electricity-1/', 'G9-PHYS-ELECTRICITY-L1', 17, 104) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G9-PHYS-ELECTRICITY-L1', 'Physics · Electricity · Lesson 1: Charge, current and circuits', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Yes", "No", "No", "Yes"], "tip": "Complete loop?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Cell", "Lamp", "Resistor", "Ammeter", "Voltmeter"], "tip": "Learn the standard set."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["0.3", "0 3"], ["same", "not used up", "series"]], "tips": ["Is current used up?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["already", "all the", "whole", "everywhere"], ["same time", "at once", "immediately", "together"]], "tips": ["Electrons are in the wire already."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["gap", "place the material", "connect"], ["bulb", "ammeter", "buzzer"], ["light", "reading", "current"], ["same", "fair", "repeat"]], "tips": ["Circuit, gap, observe."]}]}, "models": {"1": [["Q1", "The circuit is not complete (or the cells oppose each other), so charge cannot flow."], ["Q2", "Only complete circuits with a closed switch light the bulb."]], "2": [["Q3", "Cell; lamp; resistor; ammeter; voltmeter."]], "3": [["Q4", "It also reads 0.3 A [1] because current is the same at every point in a series circuit; charge is not used up by the bulb [1]."]], "4": [["Q5", "The wires are already full of electrons [1], so when the switch closes all of them start moving at the same time, and energy reaches the bulb immediately [1]."]], "5": [["Q6", "Build a circuit of a cell, bulb and wires with a gap [1]; place each material across the gap with crocodile clips [1] and include an ammeter or bulb [1]; if the bulb lights or the ammeter shows a current the material conducts; use the same cell and length of material each time [1]."]], "6": [["Exit ticket", "The flow of electric charge; amperes (A)."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('5ea7bd66-cdc8-5b4a-a78e-6250d1e1e030', '41b80b32-d95f-5bb1-b5c9-3f22d7baaf15', 'Physics · Electricity · Lesson 2: Potential difference and resistance', 'MYP 4 · Physics · Electricity', '/g9-phys-electricity-2/', 'G9-PHYS-ELECTRICITY-L2', 21, 105) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G9-PHYS-ELECTRICITY-L2', 'Physics · Electricity · Lesson 2: Potential difference and resistance', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Ammeter", "Voltmeter", "Ammeter", "Voltmeter"], "tip": "A for amps, V for volts."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["2 Ω", "6 V", "0.5 A", "10 Ω"], "tip": "V = I × R."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["6"], ["12"]], "tips": ["R = V ÷ I."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["More resistance", "Less resistance", "Less resistance", "More resistance"], "tip": "Long and thin = hard to flow."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["straight"], ["origin", "zero", "0"], ["proportional", "constant resistance", "same resistance"]], "tips": ["Line, start point, meaning."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["ammeter+voltmeter"], ["independent+length", "length"], ["same", "thickness", "material", "temperature"], ["divide", "v ÷ i", "v/i", "r =", "resistance ="]], "tips": ["Circuit, IV, CVs, calculation."]}]}, "models": {"1": [["Q1", "Ammeter: current, series. Voltmeter: p.d., parallel."]], "2": [["Q2", "R = 6 ÷ 3 = 2 Ω; V = 2 × 3 = 6 V; I = 5 ÷ 10 = 0.5 A; R = 12 ÷ 1.2 = 10 Ω."], ["Q3", "R = V ÷ I = 6 ÷ 0.5 [1] = 12 Ω [1]."]], "3": [["Q4", "Longer and thinner: more resistance. Thicker and copper: less."]], "4": [["Q5", "It is a straight line [1] through the origin [1], showing that current is directly proportional to p.d., so the resistance is constant [1]."]], "5": [["Q6", "Connect the wire in series with an ammeter and a cell, with a voltmeter across the wire [1]; change the length of wire between the clips (the independent variable) [1]; keep the same thickness and material and switch off between readings so it does not heat up [1]; calculate resistance as R = V ÷ I for each length [1]."]], "6": [["Exit ticket", "V = I × R."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('5e2e2a95-9393-595d-ac10-18de0aee5bbf', '41b80b32-d95f-5bb1-b5c9-3f22d7baaf15', 'Physics · Electricity · Lesson 3: Series and parallel circuits', 'MYP 4 · Physics · Electricity', '/g9-phys-electricity-3/', 'G9-PHYS-ELECTRICITY-L3', 18, 106) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G9-PHYS-ELECTRICITY-L3', 'Physics · Electricity · Lesson 3: Series and parallel circuits', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["3 V", "Same", "All go out"], "tip": "Share the p.d."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 1, "pts": [["1 a", "1.0", "1 amp", "1a", "= 1"]], "tips": ["Add the branches."]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 4, "n": 4, "ans": ["Series", "Parallel", "Parallel", "Series"], "tip": "Loop or branches?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["4 V", "12 V", "2 A"], "tip": "Series shares, parallel adds current."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 4, "pts": [["full", "240", "same voltage", "same p.d."], ["bright", "work properly"], ["independent", "own switch", "separately"], ["break", "fail", "stay on", "others still"]], "tips": ["Two reasons, each explained."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["parallel"], ["switch+each", "own switch", "each branch"], ["independent", "separately", "one fails", "full voltage"]], "tips": ["Branches and switches."]}]}, "models": {"1": [["Q1", "Each bulb gets 3 V; the current is the same everywhere; if one breaks, all go out."]], "2": [["Q2", "Total current = 0.4 + 0.6 = 1 A [1]."], ["Q3", "Same current and dimmer: series. Full p.d. per branch and others stay on: parallel."]], "3": [["Q4", "12 − 8 = 4 V; parallel branches each 12 V; 0.5 + 1.5 = 2 A."]], "4": [["Q5", "Each light gets the full 240 V supply [1], so all are fully bright [1]; each can be switched on and off independently [1], and if one bulb fails the others stay on [1]."]], "5": [["Q6", "Connect the two lights in parallel with the battery [1], with a switch on each branch [1], so each light can be turned on independently and gets the full battery voltage, and one failing does not affect the other [1]."]], "6": [["Exit ticket", "They stay on."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('aa8639b3-2117-5c55-be24-e633378d682c', '41b80b32-d95f-5bb1-b5c9-3f22d7baaf15', 'Physics · Electricity · Lesson 4: Electrical power, energy and safety', 'MYP 4 · Physics · Electricity', '/g9-phys-electricity-4/', 'G9-PHYS-ELECTRICITY-L4', 18, 107) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G9-PHYS-ELECTRICITY-L4', 'Physics · Electricity · Lesson 4: Electrical power, energy and safety', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["60 W", "240 W", "1200 W", "2400 W"], "tip": "P = V × I."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["1.5", "1 5"], ["3 kwh", "3kwh", "= 3"], ["75"]], "tips": ["kW × h, then × price."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Fuse", "Earth wire", "Circuit breaker", "Double insulation"], "tip": "How does each protect?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["10"], ["13"], ["just above", "higher than", "not blow", "above"]], "tips": ["I = P ÷ V."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["500 w", "0.5 kw", "50 w", "50w", "500w"], ["2.5", "2 5"], ["kwh"], ["carbon", "money", "cost", "last longer", "fuel", "environment"]], "tips": ["Power saved × time."]}]}, "models": {"1": [["Q1", "240 × 0.25 = 60 W; 240 × 1 = 240 W; 240 × 5 = 1200 W; 240 × 10 = 2400 W."]], "2": [["Q2", "Energy = 1.5 kW × 2 h [1] = 3 kWh [1]; cost = 3 × 25 = KES 75 [1]."]], "3": [["Q3", "Melts: fuse. Metal case to ground: earth. Trips: circuit breaker. Plastic case: double insulation."]], "4": [["Q4", "I = 2400 ÷ 240 = 10 A [1]; choose the 13 A fuse [1], because it is just above the normal current so it will not blow in normal use but will melt if a fault makes the current much larger [1]."]], "5": [["Q5", "Each bulb saves 60 − 10 = 50 W, so ten save 500 W = 0.5 kW [1]; energy saved = 0.5 kW × 5 h [1] = 2.5 kWh [1] per day; this also saves money and reduces carbon dioxide from power stations [1]."]], "6": [["Exit ticket", "P = V × I (power = potential difference × current)."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
