insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('5b0b8089-a93a-5462-b128-07bf68c1b0b4', '1b58a8c4-c107-51af-a262-36782a34a169', 'Chemistry · Chemical reactions · Lesson 1: Equations and conservation of mass', 'MYP 5 · Chemistry · Chemical reactions', '/g10-chem-reactions-1/', 'G10-CHEM-REACTIONS-L1', 23, 100) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G10-CHEM-REACTIONS-L1', 'Chemistry · Chemical reactions · Lesson 1: Equations and conservation of mass', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["44 g", "40 g", "44 g", "10 g"], "tip": "Mass in = mass out."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["4", "2", "6", "6", "4"], "tip": "Coefficient × subscript."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Balanced", "Not balanced", "Balanced", "Not balanced", "Balanced"], "tip": "Count each side."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["3h2", "3 h2", "3h₂"], ["2nh3", "2 nh3", "2nh₃"]], "tips": ["Balance N first."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["oxygen"], ["air", "combine", "react"], ["magnesium oxide", "atom", "total"]], "tips": ["What joined the magnesium?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["carbon dioxide", "gas"], ["escape", "left the flask", "air"], ["wrong", "not lost", "incorrect", "invalid"], ["cotton wool", "seal", "closed", "balloon", "bung"]], "tips": ["Where did the mass go?"]}]}, "models": {"1": [["Q1", "44 g; 40 g; 100 − 56 = 44 g; 90 − 80 = 10 g."]], "2": [["Q2", "4; 2; 6; 6; 2 + 2 = 4."]], "3": [["Q3", "Balanced: 2H₂ + O₂ → 2H₂O, CH₄ + 2O₂ → CO₂ + 2H₂O, 2Na + Cl₂ → 2NaCl. The others are not."], ["Q4", "N₂ + 3H₂ → 2NH₃: 2 nitrogen atoms need 2NH₃ [1], which has 6 hydrogen atoms, so 3H₂ [1]."]], "4": [["Q5", "The magnesium reacts with oxygen [1] from the air, and the oxygen atoms combine with it [1] to form magnesium oxide, so the extra mass is the oxygen; the total mass of all reactants equals the mass of products [1]."]], "5": [["Q6", "The reaction produces carbon dioxide gas [1], which escapes from the open flask into the air [1], so the conclusion is wrong: mass is not lost, it just left the system [1]; sealing the flask with a balloon or bung would show the total mass stays the same [1]."]], "6": [["Exit ticket", "H₂ + Cl₂ → 2HCl."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('fae3617c-cf3d-587e-a79f-1aa11f97e911', '1b58a8c4-c107-51af-a262-36782a34a169', 'Chemistry · Chemical reactions · Lesson 2: Types of chemical reaction', 'MYP 5 · Chemistry · Chemical reactions', '/g10-chem-reactions-2/', 'G10-CHEM-REACTIONS-L2', 23, 101) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G10-CHEM-REACTIONS-L2', 'Chemistry · Chemical reactions · Lesson 2: Types of chemical reaction', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Carbon dioxide + water", "Magnesium oxide", "Carbon dioxide + water"], "tip": "Hydrocarbons → CO₂ + H₂O."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 3, "pts": [["oxygen", "little air"], ["incomplete"], ["carbon monoxide", "toxic", "poison"]], "tips": ["Not enough oxygen…"]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["copper oxide+carbon dioxide"], ["green", "black", "limewater", "colour"]], "tips": ["One reactant, two products."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Yes", "No", "Yes", "No", "Yes"], "tip": "Is the metal more reactive?"}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Combustion", "Thermal decomposition", "Displacement", "Precipitation"], "tip": "Look at the reactants."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["iron+more reactive"], ["copper+less reactive", "cannot", "not displace"]], "tips": ["Reactivity series."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["limestone", "calcium carbonate"], ["decompos", "heat"], ["fuel", "burn", "kiln"], ["renewable", "capture", "less cement", "alternative", "recycle", "efficient"]], "tips": ["Two sources and a solution."]}]}, "models": {"1": [["Q1", "Methane and ethanol: carbon dioxide + water. Magnesium: magnesium oxide."], ["Q2", "In a closed room there is not enough oxygen [1], so the charcoal undergoes incomplete combustion [1], producing carbon monoxide, a poisonous gas that can kill [1]."]], "2": [["Q3", "Copper carbonate → copper oxide + carbon dioxide [1]; the green powder turns black (and the gas turns limewater milky) [1]."]], "3": [["Q4", "Zinc, magnesium and iron displace less reactive metals; copper and silver cannot displace more reactive ones."]], "4": [["Q5", "Petrol: combustion. Limestone: thermal decomposition. Magnesium: displacement. Yellow solid: precipitation."], ["Q6", "Iron is more reactive than copper, so it can take the sulfate from copper [1]; copper is less reactive than iron, so it cannot displace iron [1]."]], "5": [["Q7", "Limestone (calcium carbonate) [1] is thermally decomposed by strong heating, releasing carbon dioxide [1]; burning fuel to heat the kiln releases more [1]; using renewable energy or carbon capture would reduce emissions [1]."]], "6": [["Exit ticket", "Displacement."]]}, "labels": {"q1_1": "Q2", "q2_0": "Q3", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('6f922fe7-8dd4-5335-9e33-c42b99a6c4bf', '1b58a8c4-c107-51af-a262-36782a34a169', 'Chemistry · Chemical reactions · Lesson 3: Rates of reaction', 'MYP 5 · Chemistry · Chemical reactions', '/g10-chem-reactions-3/', 'G10-CHEM-REACTIONS-L3', 19, 102) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G10-CHEM-REACTIONS-L3', 'Chemistry · Chemical reactions · Lesson 3: Rates of reaction', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Faster", "Slower", "Faster", "Faster", "Slower"], "tip": "More collisions = faster."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["surface area"], ["more particles", "exposed"], ["collision", "collide"]], "tips": ["Area → particles → collisions."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["2 cm³/s", "0.5 cm³/s", "4 cm³/s", "1 cm³/s"], "tip": "Volume ÷ time."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["faster", "kinetic energy", "more energy"], ["more often", "more frequent", "frequency"], ["activation energy", "successful", "enough energy"]], "tips": ["Two effects of heating."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["independent+concentration"], ["gas syringe", "volume", "time", "stopwatch"], ["same length", "same mass", "same temperature", "same volume"], ["error", "reaction time", "gas escape", "repeat"]], "tips": ["IV, DV, CVs, error."]}]}, "models": {"1": [["Q1", "Stir, use hotter tea, use granulated or powdered sugar instead of a cube; hotter and smaller pieces also speed up reactions."], ["Q2", "Higher temperature, powder and a catalyst speed it up; lower concentration and cooling slow it down."]], "2": [["Q3", "Powder has a larger surface area [1], so more particles of marble are exposed to the acid [1], giving more frequent collisions and a faster rate [1]."]], "3": [["Q4", "60/30 = 2; 30/60 = 0.5; 40/10 = 4; 20/20 = 1 cm³/s."]], "4": [["Q5", "Particles move faster with more kinetic energy [1], so they collide more often [1] and more of the collisions have at least the activation energy, so more are successful [1]."]], "5": [["Q6", "Change the concentration of the acid (independent variable) [1]; measure the volume of hydrogen in a gas syringe every 10 s or the time for the magnesium to disappear [1]; keep the same length of magnesium, volume of acid and temperature [1]; a source of error is reaction time when starting the stopwatch, so repeat and average [1]."]], "6": [["Exit ticket", "Temperature, concentration (or pressure), surface area, catalyst."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('657927fc-3f14-5a5d-9594-e68636ea6403', '1b58a8c4-c107-51af-a262-36782a34a169', 'Chemistry · Chemical reactions · Lesson 4: Energy changes in reactions', 'MYP 5 · Chemistry · Chemical reactions', '/g10-chem-reactions-4/', 'G10-CHEM-REACTIONS-L4', 18, 103) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G10-CHEM-REACTIONS-L4', 'Chemistry · Chemical reactions · Lesson 4: Energy changes in reactions', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Exothermic", "Endothermic", "Exothermic", "Endothermic", "Exothermic", "Endothermic"], "tip": "Hotter = exo."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["8"], ["exothermic"]], "tips": ["Final − initial."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Exothermic", "Endothermic", "Activation energy"], "tip": "Where do products sit?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["break", "breaking"], ["making", "form", "new bonds"], ["more", "greater", "larger"]], "tips": ["Compare in and out."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["endothermic"], ["take in", "absorb", "from the surroundings", "cools"], ["safe", "non-toxic", "sealed", "not leak"], ["cheap", "squeeze", "mix", "quick", "long", "reusable", "portable"]], "tips": ["Type + design features."]}]}, "models": {"1": [["Q1", "Burning, neutralisation and a rising temperature: exothermic. Photosynthesis, decomposition and a falling temperature: endothermic."]], "2": [["Q2", "Temperature change = 29 − 21 = +8 °C [1]; it is exothermic because the temperature rose [1]."]], "3": [["Q3", "Lower products: exothermic. Higher: endothermic. Hump: activation energy."]], "4": [["Q4", "Energy is needed to break the bonds in methane and oxygen [1]; energy is released when new bonds form in carbon dioxide and water [1]; more energy is released making bonds than is taken in breaking them, so overall energy is given out [1]."]], "5": [["Q5", "It needs an endothermic reaction [1], which takes in energy from the surroundings so the pack cools the injury [1]; the chemicals must be safe and sealed so they cannot leak [1], and it should be cheap and start quickly when squeezed to mix the chemicals [1]."]], "6": [["Exit ticket", "It rises."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('300c8b28-0524-519e-be9c-30327cb7fda3', 'bf762275-02e5-5601-8f36-41f5161c9ff1', 'Physics · Waves · Lesson 1: Properties of waves', 'MYP 5 · Physics · Waves', '/g10-phys-waves-1/', 'G10-PHYS-WAVES-L1', 21, 104) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G10-PHYS-WAVES-L1', 'Physics · Waves · Lesson 1: Properties of waves', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Transverse", "Longitudinal", "Transverse", "Longitudinal", "Transverse"], "tip": "Right angles or parallel?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Wavelength", "Frequency", "Amplitude", "Period"], "tip": "Distance, number, height, time."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["10 m/s", "340 m/s", "2 m", "50 Hz"], "tip": "v = f × λ."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["0.5", "0 5"], ["2 m"]], "tips": ["v = f × λ."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["up and down", "bob", "same place"], ["energy+move", "energy+travel", "not move along", "does not travel"]], "tips": ["Watch the cork."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["amplitude+small", "low amplitude", "small height"], ["slow", "shallow"], ["amplitude+increase", "taller", "height increase", "grow"], ["warning", "sensor", "buoy", "evacuat", "seismic"]], "tips": ["Deep vs shallow; warning systems."]}]}, "models": {"1": [["Q1", "Light, ripples and radio: transverse. Sound and the pushed slinky: longitudinal."]], "2": [["Q2", "Crest to crest: wavelength. Per second: frequency. Height: amplitude. Time for one: period."]], "3": [["Q3", "5 × 2 = 10 m/s; 170 × 2 = 340 m/s; 20 ÷ 10 = 2 m; 100 ÷ 2 = 50 Hz."], ["Q4", "v = 0.5 × 4 [1] = 2 m/s [1]."]], "4": [["Q5", "The cork moves up and down and stays in the same place [1], showing the water does not travel with the wave; only the energy moves along [1]."]], "5": [["Q6", "In deep water the wave has a small amplitude, so ships hardly notice it [1]; as it reaches shallow water it slows down [1] and its amplitude increases enormously, carrying huge energy onto land [1]; warning systems using seismic sensors and ocean buoys give time to evacuate [1]."]], "6": [["Exit ticket", "v = f × λ; hertz (Hz)."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) values ('b384dd50-99b6-55ab-93b3-538317c8776a', 'bf762275-02e5-5601-8f36-41f5161c9ff1', 'Physics · Waves · Lesson 2: Sound', 'MYP 5 · Physics · Waves', '/g10-phys-waves-2/', 'G10-PHYS-WAVES-L2', 18, 105) on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G10-PHYS-WAVES-L2', 'Physics · Waves · Lesson 2: Sound', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["quieter", "fades", "cannot hear", "silent"], ["vacuum", "no particles", "no air", "medium"]], "tips": ["Remove the medium."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Fastest", "Middle", "Slowest"], "tip": "Particles closer = faster."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["340"], ["1020"]], "tips": ["Distance = speed × time."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Higher pitch", "Louder", "Lower pitch", "Quieter"], "tip": "Frequency = pitch; amplitude = loudness."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["3000"], ["divide by 2", "÷ 2", "there and back", "half"], ["1500 m"]], "tips": ["There and back!"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["damage", "hearing loss", "deaf"], ["hair cell", "ear", "amplitude", "loud"], ["lower volume", "turn down", "quieter"], ["break", "less time", "shorter", "limit", "noise-cancel"]], "tips": ["Risk + two actions."]}]}, "models": {"1": [["Q1", "The sound gets quieter until it cannot be heard [1] because there are no air particles to carry the vibrations; sound cannot travel through a vacuum [1]."]], "2": [["Q2", "Steel fastest, water middle, air slowest."], ["Q3", "Distance = 340 × 3 [1] = 1020 m [1]."]], "3": [["Q4", "Closer: higher pitch. Taller: louder. Further apart: lower pitch. Shorter: quieter."]], "4": [["Q5", "Distance travelled = 1500 × 2 = 3000 m [1]; this is there and back, so divide by 2 [1]; depth = 1500 m [1]."]], "5": [["Q6", "Loud sound for long periods can cause permanent hearing loss [1] because the large-amplitude vibrations damage the hair cells in the inner ear [1]; turn the volume down to below about 60% [1] and take regular breaks or use noise-cancelling headphones so lower volumes are enough [1]."]], "6": [["Exit ticket", "Frequency."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
