insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G10-PHYS-WAVES-L3', 'Physics · Waves · Lesson 3: Light: reflection and refraction', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["35°", "50°", "20°", "70°"], "tip": "Measure from the normal!"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Towards the normal", "Away from the normal", "No bending", "Away from the normal"], "tip": "Slows = towards."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["water+air", "leaves the water"], ["away from the normal", "bend", "refract", "speed"], ["straight line", "brain", "eye", "higher", "appear"]], "tips": ["Ray from the bottom to your eye."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["total internal reflection"], ["critical angle", "greater than", "large angle"], ["reflect", "bounce"]], "tips": ["Angle → reflection."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["ray box", "laser"], ["protractor"], ["independent+angle of incidence", "angle of incidence"], ["normal", "pencil", "dark", "repeat", "thin ray"]], "tips": ["Equipment, IV, DV, accuracy."]}]}, "models": {"1": [["Q1", "35°; 50°; 20° (from normal); 70° (90 − 20)."]], "2": [["Q2", "Air→glass: towards. Water→air: away. Along normal: no bending. Glass→air: away."]], "3": [["Q3", "Light from the bottom of the pool passes from water into air [1] and refracts away from the normal as it speeds up [1]; your brain assumes light travels in straight lines, so the bottom appears higher than it is [1]."]], "4": [["Q4", "Light travels by total internal reflection [1]: it hits the inside surface of the fibre at an angle greater than the critical angle [1], so it is completely reflected and bounces along the fibre even round bends [1]."]], "5": [["Q5", "Use a ray box to shine a thin ray into a glass block on paper [1]; draw the normal and measure angles with a protractor [1]; change the angle of incidence (independent variable) from 10° to 70° and measure the angle of refraction [1]; mark the rays with pencil dots in a darkened room and repeat for accuracy [1]."]], "6": [["Exit ticket", "The angle of incidence equals the angle of reflection."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
