insert into public.lesson_specs (lesson, title, spec, updated_at) values ('G10-PHYS-WAVES-L4', 'Physics · Waves · Lesson 4: The electromagnetic spectrum', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 7, "n": 7, "ans": ["1", "2", "3", "4", "5", "6", "7"], "tip": "Rich Men In Vegas…"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["transverse"], ["speed", "vacuum", "energy", "reflect"]], "tips": ["Type and speed."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Infrared", "X-rays", "Radio waves", "Microwaves", "Gamma rays", "Ultraviolet"], "tip": "Match the job."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["ionising", "damage", "cancer", "dna"], ["many", "repeated", "every day", "exposure", "dose"], ["benefit", "one", "small", "single", "occasional"]], "tips": ["Dose and benefit."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["microwave", "radio"], ["low frequency", "low energy", "non-ionising", "not ionising"], ["heat", "warming"], ["conclu", "evidence", "research", "small risk", "safe", "limit"]], "tips": ["Wave type, energy, evidence, judgement."]}]}, "models": {"1": [["Q1", "Radio 1, microwaves 2, infrared 3, visible 4, UV 5, X-rays 6, gamma 7."]], "2": [["Q2", "They are all transverse waves [1] and all travel at the same speed in a vacuum, 300 000 000 m/s [1]."]], "3": [["Q3", "Remote: infrared. Bone: X-rays. FM: radio. Phones: microwaves. Cancer: gamma. Banknotes: UV."]], "4": [["Q4", "X-rays are ionising and can damage DNA, causing cancer [1]; radiographers take many X-rays every day, so their total dose would be large [1]; a patient has a single small dose, and the benefit of diagnosing the injury outweighs the small risk [1]."]], "5": [["Q5", "Mobile phones use microwaves and radio waves [1], which have low frequency and energy and are non-ionising, so they cannot damage DNA like X-rays [1]; very strong microwaves can heat tissue, but masts are far below that level [1]; current research shows no clear evidence of harm, so the risk is very small, though exposure limits are sensible [1]."]], "6": [["Exit ticket", "Infrared; gamma rays."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
